#!/usr/bin/env node
//
// scripts/upgradeable/split-withinit.js
//
// Split the monolithic `contracts/mocks/WithInit.sol` (generated by
// hardhat-exposed `initializers: true`, then committed as part of the
// transpiled upgradeable output) into several smaller files so the
// tron-solc 0.8.26 wasm build can compile them.
//
// WHY: WithInit.sol bundles ~190 `*WithInit` constructor variants in ONE
// file, so its transitive import closure is essentially the ENTIRE corpus
// (~300 sources). tron-solc OOMs ("memory access out of bounds") well below
// that — empirically a single pass tops out around ~90 sources. The existing
// `tron-batches.config.cjs` mock chunker only regroups the OTHER top-level
// mock FILES; it cannot shrink a single monolithic file's closure, so no
// CHUNK value makes WithInit.sol compile.
//
// HOW: parse WithInit.sol into (import, contract) units, compute each unit's
// transitive source closure (applying remappings so peer + local sources are
// counted), then greedy bin-pack units into output files such that each
// output file's UNION closure stays under THRESHOLD sources. Contract NAMES
// are preserved verbatim (the test suite resolves `XUpgradeableWithInit` via
// the hardhat/env-artifacts.js suffix shim), only their file grouping changes.
//
// Output: contracts/mocks/withinit/WithInit_<NN>.sol  (monolith removed).
// `tron-batches.config.cjs` compiles each as its own pass.
//
// Idempotent: re-running regenerates the split set from scratch. If only the
// already-split files exist (no monolith), it is a no-op.
//

'use strict';

const fs = require('node:fs');
const path = require('node:path');

const ROOT = path.resolve(__dirname, '../..');
const MONOLITH = path.join(ROOT, 'contracts/mocks/WithInit.sol');
const OUT_DIR = path.join(ROOT, 'contracts/mocks/withinit');

// Max source files in a single output file's transitive closure. token-mocks
// (57) and governance (45) compile cleanly; the wasm wall is ~91+. 75 leaves
// headroom for the shared utils/access core that every bin drags in.
const THRESHOLD = Number(process.env.WITHINIT_THRESHOLD || 75);

// ---- remappings (mirror remappings.txt) ---------------------------------
const REMAPPINGS = fs
  .readFileSync(path.join(ROOT, 'remappings.txt'), 'utf8')
  .split('\n')
  .map(l => l.trim())
  .filter(Boolean)
  .map(l => l.split('='));

function resolveImport(fromFile, spec) {
  for (const [prefix, target] of REMAPPINGS) {
    if (spec.startsWith(prefix)) {
      return path.join(ROOT, target, spec.slice(prefix.length));
    }
  }
  if (spec.startsWith('.')) {
    return path.resolve(path.dirname(fromFile), spec);
  }
  // bare node_modules-style import (e.g. a non-remapped package); best-effort
  return path.join(ROOT, 'node_modules', spec);
}

const IMPORT_RE = /import\s+(?:[^"';]*\sfrom\s+)?["']([^"']+)["']/g;

function readImports(file) {
  let src;
  try {
    src = fs.readFileSync(file, 'utf8');
  } catch {
    return [];
  }
  const out = [];
  let m;
  IMPORT_RE.lastIndex = 0;
  while ((m = IMPORT_RE.exec(src)) !== null) out.push(m[1]);
  return out;
}

const closureCache = new Map();
function closureOf(file) {
  const key = path.normalize(file);
  if (closureCache.has(key)) return closureCache.get(key);
  const seen = new Set();
  const stack = [key];
  while (stack.length) {
    const f = path.normalize(stack.pop());
    if (seen.has(f)) continue;
    if (!fs.existsSync(f)) continue; // unresolved (e.g. missing peer) — skip
    seen.add(f);
    for (const spec of readImports(f)) {
      stack.push(resolveImport(f, spec));
    }
  }
  closureCache.set(key, seen);
  return seen;
}

// ---- parse the monolith into units --------------------------------------
function parseUnits(src) {
  const lines = src.split('\n');
  const units = [];
  let pendingImports = [];
  for (let i = 0; i < lines.length; i++) {
    const line = lines[i];
    if (/^\s*import\s/.test(line)) {
      pendingImports.push(line);
      continue;
    }
    const cm = line.match(/^\s*contract\s+([A-Za-z0-9_$]+)\s/);
    if (cm) {
      // capture the contract block via brace matching
      let depth = 0;
      let started = false;
      const body = [];
      let j = i;
      for (; j < lines.length; j++) {
        const l = lines[j];
        body.push(l);
        for (const ch of l) {
          if (ch === '{') {
            depth++;
            started = true;
          } else if (ch === '}') depth--;
        }
        if (started && depth === 0) break;
      }
      units.push({
        name: cm[1],
        imports: pendingImports.slice(),
        body: body.join('\n'),
      });
      pendingImports = [];
      i = j;
    }
  }
  return units;
}

function main() {
  if (!fs.existsSync(MONOLITH)) {
    if (fs.existsSync(OUT_DIR)) {
      console.log('WithInit.sol already split; nothing to do.');
      return;
    }
    console.error(`error: ${MONOLITH} not found`);
    process.exit(1);
  }

  const src = fs.readFileSync(MONOLITH, 'utf8');
  // preserve the header (license + pragmas) before the first import/contract
  const headerLines = [];
  for (const line of src.split('\n')) {
    if (/^\s*(import|contract)\s/.test(line)) break;
    headerLines.push(line);
  }
  const header = headerLines.join('\n').trimEnd() + '\n';

  const units = parseUnits(src);
  console.log(`parsed ${units.length} WithInit units from monolith`);

  // closure size per unit (resolve each import relative to the OUT_DIR, since
  // that's where the split files will live — paths shift from mocks/ to
  // mocks/withinit/, so imports gain one `../`).
  for (const u of units) {
    const cl = new Set();
    for (const imp of u.imports) {
      const spec = imp.match(/["']([^"']+)["']/)[1];
      for (const f of closureOf(resolveImport(MONOLITH, spec))) cl.add(f);
    }
    u.closure = cl;
  }

  // greedy bin-pack: sort by closure size desc, place each in the first bin
  // whose union stays <= THRESHOLD, else open a new bin.
  units.sort((a, b) => b.closure.size - a.closure.size);
  const bins = [];
  for (const u of units) {
    let placed = false;
    for (const bin of bins) {
      const union = new Set(bin.closure);
      for (const f of u.closure) union.add(f);
      if (union.size <= THRESHOLD) {
        bin.units.push(u);
        bin.closure = union;
        placed = true;
        break;
      }
    }
    if (!placed) {
      bins.push({ units: [u], closure: new Set(u.closure) });
    }
  }

  // write output
  fs.rmSync(OUT_DIR, { recursive: true, force: true });
  fs.mkdirSync(OUT_DIR, { recursive: true });

  bins.forEach((bin, idx) => {
    const nn = String(idx + 1).padStart(2, '0');
    // re-base each import path by one extra `../` (file moved mocks/ -> mocks/withinit/)
    const seenImports = new Set();
    const parts = [];
    for (const u of bin.units) {
      for (const imp of u.imports) {
        const rebased = imp.replace(/(["'])(\.\.?\/)/, (mm, q, dots) => (dots === './' ? `${q}../` : `${q}../${dots}`));
        if (!seenImports.has(rebased)) {
          seenImports.add(rebased);
          parts.push(rebased);
        }
      }
    }
    parts.push('');
    for (const u of bin.units) parts.push(u.body, '');
    const content =
      header +
      '\n' +
      parts
        .join('\n')
        .replace(/\n{3,}/g, '\n\n')
        .trimEnd() +
      '\n';
    const file = path.join(OUT_DIR, `WithInit_${nn}.sol`);
    fs.writeFileSync(file, content);
    console.log(`  WithInit_${nn}.sol: ${bin.units.length} units, closure ${bin.closure.size} sources`);
  });

  fs.rmSync(MONOLITH, { force: true });
  console.log(`removed monolith; wrote ${bins.length} files to contracts/mocks/withinit/`);
}

main();
